# Graph Data Structures in Python

## Overview
Building and validating graph structures with nodes and edges for dialogue systems, state machines, and flow charts.

## Core Data Structure

### Simple Graph Representation
```python
class Graph:
    def __init__(self):
        self.nodes = []
        self.edges = []

    def add_node(self, node_id: str, node_type: str, text: str = "", speaker: str = None):
        node = {
            'id': node_id,
            'type': node_type,
            'text': text
        }
        if speaker:
            node['speaker'] = speaker
        self.nodes.append(node)

    def add_edge(self, from_id: str, to_id: str, text: str = ""):
        edge = {
            'from': from_id,
            'to': to_id
        }
        if text:
            edge['text'] = text
        self.edges.append(edge)

    def to_dict(self):
        return {
            'nodes': self.nodes,
            'edges': self.edges
        }
```

## Graph Validation

### 1. Check All Nodes Reachable from Start
```python
def is_reachable_from_start(graph_dict, start_node_id):
    """BFS to check if all nodes are reachable from start."""
    if not graph_dict['nodes']:
        return True

    # Build adjacency list
    adjacency = {}
    for edge in graph_dict['edges']:
        from_node = edge['from']
        to_node = edge['to']
        if from_node not in adjacency:
            adjacency[from_node] = []
        adjacency[from_node].append(to_node)

    # BFS
    visited = set()
    queue = [start_node_id]

    while queue:
        current = queue.pop(0)
        if current in visited:
            continue
        visited.add(current)

        if current in adjacency:
            for neighbor in adjacency[current]:
                if neighbor not in visited:
                    queue.append(neighbor)

    # Check if all nodes are visited
    all_node_ids = {node['id'] for node in graph_dict['nodes']}
    unreachable = all_node_ids - visited

    return len(unreachable) == 0, unreachable
```

### 2. Validate Edge Targets Exist
```python
def validate_edge_targets(graph_dict, allowed_missing=None):
    """Check that all edge targets reference existing nodes."""
    if allowed_missing is None:
        allowed_missing = set()

    node_ids = {node['id'] for node in graph_dict['nodes']}
    errors = []

    for edge in graph_dict['edges']:
        target = edge['to']
        if target not in node_ids and target not in allowed_missing:
            errors.append(f"Edge from '{edge['from']}' references non-existent node '{target}'")

    return len(errors) == 0, errors
```

### 3. Find Terminal Nodes
```python
def find_terminal_nodes(graph_dict):
    """Find nodes with no outgoing edges."""
    nodes_with_outgoing = {edge['from'] for edge in graph_dict['edges']}
    all_nodes = {node['id'] for node in graph_dict['nodes']}
    terminal = all_nodes - nodes_with_outgoing
    return terminal
```

## Usage Example

```python
# Build graph
graph = Graph()
graph.add_node('start', 'line', 'Welcome!', 'Narrator')
graph.add_node('choice1', 'choice', 'What do you do?')
graph.add_edge('start', 'choice1')

# Convert to dict
graph_dict = graph.to_dict()

# Validate
reachable, unreachable = is_reachable_from_start(graph_dict, 'start')
valid, errors = validate_edge_targets(graph_dict, allowed_missing={'End'})
```

## Best Practices

1. **Use consistent node IDs** - avoid special characters that might break formats
2. **Validate early** - check graph structure before serialization
3. **Handle cycles** - use visited sets in traversal algorithms
4. **Allow terminal nodes** - some graphs naturally end without explicit End nodes

